template <> struct Prep<GT_IQ3_S> {
    static constexpr int BLOCK_BYTES = 110, UPB = 8;
    static __device__ __forceinline__ void run(const uint8_t * blk, int ib32, UnitW & u) {
        const float d = half_at(blk);
